CREATE DATABASE banking_analytics_db;

USE banking_analytics_db;

SELECT DB_NAME() AS current_database;

CREATE SCHEMA gold;

CREATE VIEW gold.vw_customer_360
AS
SELECT *
FROM OPENROWSET(
    BULK 'https://adlsbankinganalytics.dfs.core.windows.net/gold/customer_360',
    FORMAT = 'DELTA'
) AS customer_data;


CREATE VIEW gold.vw_fraud_analysis
AS
SELECT *
FROM OPENROWSET(
    BULK 'https://adlsbankinganalytics.dfs.core.windows.net/gold/fraud_analysis',
    FORMAT = 'DELTA'
) AS fraud_data;


CREATE VIEW gold.vw_monthly_financial
AS
SELECT *
FROM OPENROWSET(
    BULK 'https://adlsbankinganalytics.dfs.core.windows.net/gold/monthly_financial_summary',
    FORMAT = 'DELTA'
) AS financial_data;



SELECT *
FROM gold.vw_customer_360;

SELECT *
FROM gold.vw_fraud_analysis;

SELECT *
FROM gold.vw_monthly_financial;
